<workspace>

Make exactly two files change. Do NOT modify any other files. Do NOT run git add / git commit / git stage. Leave all changes unstaged. Use the `edit`/patch capability to modify files (do not rewrite whole files with shell redirection).

GOAL: Fix the Set-Cookie merge bug in `Context.res` setter. When `this.#res` (already-set response, e.g. middleware set a cookie on c.res) and a newly assigned `_res` (handler's Response with its own Set-Cookie) both have Set-Cookie headers, BOTH sets of cookies must survive. Currently the setter deletes ALL of the new response's Set-Cookie headers and re-appends only the old response's cookies.

=== EDIT 1: src/context.ts ===
Find this exact block (currently around lines 414-434):

```
  set res(_res: Response | undefined) {
    if (this.#res && _res) {
      _res = createResponseInstance(_res.body, _res)
      for (const [k, v] of this.#res.headers.entries()) {
        if (k === 'content-type') {
          continue
        }
        if (k === 'set-cookie') {
          const cookies = this.#res.headers.getSetCookie()
          _res.headers.delete('set-cookie')
          for (const cookie of cookies) {
            _res.headers.append('set-cookie', cookie)
          }
        } else {
          _res.headers.set(k, v)
        }
      }
    }
    this.#res = _res
    this.finalized = true
  }
```

Replace it with EXACTLY:

```
  set res(_res: Response | undefined) {
    if (this.#res && _res) {
      _res = createResponseInstance(_res.body, _res)
      for (const [k, v] of this.#res.headers.entries()) {
        if (k === 'content-type' || k === 'set-cookie') {
          continue
        }
        _res.headers.set(k, v)
      }
      // `set-cookie` cannot be merged with `Headers.set()` because it would
      // overwrite the cookies already present on the new response. Append the
      // existing cookies instead so that cookies set by both the middleware and
      // the handler survive.
      for (const cookie of this.#res.headers.getSetCookie()) {
        _res.headers.append('set-cookie', cookie)
      }
    }
    this.#res = _res
    this.finalized = true
  }
```

IMPORTANT: `Headers.entries()` yields one entry per Set-Cookie value, so Set-Cookie must be handled OUTSIDE the loop (as above) to avoid duplicate appends. Do not move the append loop inside the iteration.

=== EDIT 2: src/context.test.ts ===
(a) Update the existing test whose old expectation encodes the buggy "drop new cookies" behavior. Find this exact test (around lines 430-445):

```
  it('Should set cookie headers when re-assigning Response to `c.res`', () => {
    const cookies = ['foo=bar; Path=/', 'foo2=bar2; Path=/']
    const res = new Response(null)
    res.headers.append('set-cookie', cookies[0])
    res.headers.append('set-cookie', cookies[1])
    c.res = res
    expect(c.res.headers.getSetCookie().length).toBe(2)

    // Re-assign
    const newCookies = ['foo3=bar3; Path=/']
    const newResponse = new Response(null)
    newResponse.headers.append('set-cookie', newCookies[0])
    c.res = newResponse
    expect(c.res.headers.getSetCookie().length).toBe(cookies.length)
    expect(c.res.headers.getSetCookie()).toEqual(cookies)
  })
```

Replace it with EXACTLY:

```
  it('Should set cookie headers when re-assigning Response to `c.res`', () => {
    const cookies = ['foo=bar; Path=/', 'foo2=bar2; Path=/']
    const res = new Response(null)
    res.headers.append('set-cookie', cookies[0])
    res.headers.append('set-cookie', cookies[1])
    c.res = res
    expect(c.res.headers.getSetCookie().length).toBe(2)

    // Re-assign: cookies from both responses must be preserved
    const newCookies = ['foo3=bar3; Path=/']
    const newResponse = new Response(null)
    newResponse.headers.append('set-cookie', newCookies[0])
    c.res = newResponse
    expect(c.res.headers.getSetCookie().length).toBe(cookies.length + newCookies.length)
    expect(c.res.headers.getSetCookie()).toEqual([...newCookies, ...cookies])
  })
```

(b) Add a NEW regression test immediately after the test above (before the next `it('Should keep previous cookies in response headers', ...)`). Insert EXACTLY:

```
  it('Should preserve Set-Cookie headers from both c.res and a newly assigned Response', () => {
    // Middleware has already set a cookie on c.res
    c.res.headers.append('set-cookie', 'middleware=1; Path=/')

    // The handler returns a new Response with its own Set-Cookie header
    const handlerResponse = new Response('ok', {
      headers: { 'Set-Cookie': 'handler=1; Path=/' },
    })
    c.res = handlerResponse

    const cookies = c.res.headers.getSetCookie()
    expect(cookies).toContain('middleware=1; Path=/')
    expect(cookies).toContain('handler=1; Path=/')
    expect(cookies).toHaveLength(2)
  })
```

